import Foundation

/// Decides what is never recorded. Password managers mark their copies with well-known pasteboard
/// types; we honour those, plus an ignore list of apps.
public enum CaptureRules {
    /// Pasteboard types that mean "do not keep this" (nspasteboard.org convention and password managers).
    public static let skipTypes: Set<String> = [
        "org.nspasteboard.ConcealedType", "org.nspasteboard.TransientType", "org.nspasteboard.AutoGeneratedType",
        "com.agilebits.onepassword", "com.typeit4me.clipping", "de.petermaurer.TransientPasteboardType",
        "com.apple.is-remote-clipboard",
    ]

    public static func shouldSkip(types: [String], frontBundle: String?, settings: ClipboardSettings) -> Bool {
        if types.contains(where: skipTypes.contains) { return true }
        if let b = frontBundle, settings.ignoredBundles.contains(b) { return true }
        return false
    }

    /// Case- and accent-insensitive form used for searching.
    public static func fold(_ s: String) -> String {
        s.folding(options: [.caseInsensitive, .diacriticInsensitive], locale: nil)
    }

    public static func preview(of capture: ClipCapture) -> String {
        switch capture.kind {
        case .text: return String((capture.text ?? "").prefix(400))
        case .files: return capture.files.map { ($0 as NSString).lastPathComponent }.joined(separator: ", ")
        case .image: return "Image"
        }
    }
}
